CREATE TABLE a.l_doctrine_link(id uuid PRIMARY KEY,src_id uuid NOT NULL REFERENCES a.d_doctrine_section(id),dst_doctrine_document uuid REFERENCES a.d_doctrine_document(id),dst_doctrine_section uuid REFERENCES a.d_doctrine_section(id),dst_party uuid REFERENCES a.d_party(id),dst_deal uuid REFERENCES a.d_deal(id),dst_decision uuid REFERENCES a.d_decision(id),dst_rule uuid REFERENCES a.d_rule(id),dst_loop uuid REFERENCES a.d_loop(id),dst_capture uuid REFERENCES a.d_capture(id),CHECK(num_nonnulls(dst_doctrine_document,dst_doctrine_section,dst_party,dst_deal,dst_decision,dst_rule,dst_loop,dst_capture)=1),dst_kind text GENERATED ALWAYS AS (CASE WHEN dst_doctrine_document IS NOT NULL THEN 'doctrine_document' WHEN dst_doctrine_section IS NOT NULL THEN 'doctrine_section' WHEN dst_party IS NOT NULL THEN 'party' WHEN dst_deal IS NOT NULL THEN 'deal' WHEN dst_decision IS NOT NULL THEN 'decision' WHEN dst_rule IS NOT NULL THEN 'rule' WHEN dst_loop IS NOT NULL THEN 'loop' WHEN dst_capture IS NOT NULL THEN 'capture' END) STORED,dst_id uuid GENERATED ALWAYS AS (coalesce(dst_doctrine_document,dst_doctrine_section,dst_party,dst_deal,dst_decision,dst_rule,dst_loop,dst_capture)) STORED,relation text NOT NULL CHECK(relation IN ('citation','related','example','source')),UNIQUE(src_id,dst_kind,dst_id,relation));
