CREATE TABLE a.l_incident_link(id uuid PRIMARY KEY,src_id uuid NOT NULL REFERENCES a.d_incident(id),dst_run uuid REFERENCES a.d_run(id),dst_deployment uuid REFERENCES a.d_deployment(id),dst_work_request uuid REFERENCES a.d_work_request(id),dst_defect uuid REFERENCES a.d_defect(id),dst_decision uuid REFERENCES a.d_decision(id),CHECK(num_nonnulls(dst_run,dst_deployment,dst_work_request,dst_defect,dst_decision)=1),dst_kind text GENERATED ALWAYS AS (CASE WHEN dst_run IS NOT NULL THEN 'run' WHEN dst_deployment IS NOT NULL THEN 'deployment' WHEN dst_work_request IS NOT NULL THEN 'work_request' WHEN dst_defect IS NOT NULL THEN 'defect' WHEN dst_decision IS NOT NULL THEN 'decision' END) STORED,dst_id uuid GENERATED ALWAYS AS (coalesce(dst_run,dst_deployment,dst_work_request,dst_defect,dst_decision)) STORED,relation text NOT NULL CHECK(relation IN ('reference')),UNIQUE(src_id,dst_kind,dst_id,relation));
