CREATE VIEW a.relationships AS SELECT id,'doctrine_link'::text family,'doctrine_section'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_doctrine_link UNION ALL SELECT id,'incident_link'::text family,'incident'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_incident_link UNION ALL SELECT id,'siep_evidence_link'::text family,'siep_package'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_siep_evidence_link UNION ALL SELECT id,'f01_derivative_link'::text family,'f01_corporate_artifact'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_f01_derivative_link UNION ALL SELECT id,'j102_document_link'::text family,'f01_document'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_j102_document_link UNION ALL SELECT id,'j102_artifact_link'::text family,'f01_corporate_artifact'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_j102_artifact_link UNION ALL SELECT id,'event'::text family,'event'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_event UNION ALL SELECT id,'record_source'::text family,'record_source'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_record_source UNION ALL SELECT id,'next_action'::text family,'next_action'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_next_action UNION ALL SELECT id,'record_flag'::text family,'record_flag'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_record_flag UNION ALL SELECT id,'attachment'::text family,'attachment'::text src_kind,src_id,dst_kind,dst_id,relation FROM a.l_attachment;
